    const re = /vertex\\s+([-+\\d.eE]+)\\s+([-+\\d.eE]+)\\s+([-+\\d.eE]+)/g;
    const arr = []; let m;
    while ((m = re.exec(text))) arr.push(+m[1], +m[2], +m[3]);
