// ------------------------------------------------------------------ cuts
// A cut is { x, y, ang, lateral, style }: a point on the cut line, the direction the
// cut faces (degrees from X), an optional hinge offset along the cut, and an optional style.
const AXI = () => (S.axis === 'y' ? 1 : 0);
const baseAng = () => (S.axis === 'y' ? 90 : 0);
function axisRange() { const b = S.mesh.bbox; return [b.min[AXI()], b.max[AXI()]]; }
function crossMid() { const b = S.mesh.bbox, c = 1 - AXI(); return (b.min[c] + b.max[c]) / 2; }
function jointPoint(s) { return S.axis === 'y' ? [crossMid(), s] : [s, crossMid()]; }
