        if (S.bs[b.id].stroke !== 'drag') h += slider('bSpacing', 'Spacing', bk + '.spacing', 0.05, 1, 0.01, '%') + slider('bLazy', 'Lazy mouse', 'lazy', 0, 120, 1, 'lazy');
