    const map = (p) => p.map((v, k) => { const c = (lo[k] + hi[k]) / 2, half = ((hi[k] - lo[k]) / 2) * shrink[k], bc = (bl[k] + bh[k]) / 2, bhalf = Math.max(1e-6, (bh[k] - bl[k]) / 2); return c + ((v - bc) / bhalf) * half; });
